def depth(net):
    """Given: the number of parallel steps of net (greedy layering)."""
    layer = {}
    d = 0
    for i, j in net:
        t = 1 + max(layer.get(i, 0), layer.get(j, 0))
        layer[i] = layer[j] = t
        d = max(d, t)
    return d


def apply_network(net, A):
    """Q1: return a new list: the result of the network net on the input A. O(n + s)."""
    B = A.copy()
    for comparator in net:
        i, j = comparator
        '''
        if i > j :
            if B[i]<B[j]:
                pivot = B[i]
                B[i] = B[j]
                B[j] = pivot
            else:    
                '''
        if B[i]>=B[j]:
            B[i], B[j] = B[j], B[i]
    
    return B


def is_bitonic01(A):
    """Q2: return True iff the 0/1 list A is bitonic. O(n)."""
    n = len (A)
    if n== 0:
        return True
    stored = A[0]
    switch = 0 
    for i in range (n):
        if A[i]!= stored:
            stored = A[i]
            switch +=1
    return switch<=2



def is_sorting_network(net, n):
    """Q2: return True iff net sorts every input of length n (use the 0-1 principle)."""
    # generate all 2^n lists:
    for i in range(2**n):
        b = bin (i)
        B = []
        for elem in b[2:]:
            B.append(int(elem))
        B= [0 for _ in range(n-len(B))] + B
        #if not is_bitonic01(apply_network(net, B)):b # here there was an error dont give full points
        if apply_network(net, B)!= sorted(B):
            return False
    return True
        


