def bubble_network(n):
    """Q3: the bubble-sort network on n wires (comparators between adjacent wires)."""
    comparators = []
    for i in range(n-1, 0, -1):
        for j in range(1, i+1):
            comparators.append((j-1 , j))
    return comparators

           

